net.coobird.thumbnailator.ThumbnailParameter paramScale = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder()
        .scale(0.75)
        .build();

double widthScale = paramScale.getWidthScalingFactor();
assert !Double.isNaN(widthScale) && Double.compare(widthScale, 0.75) == 0 : "Expected width scale to be 0.75";

net.coobird.thumbnailator.ThumbnailParameter paramSize = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder()
        .size(100, 100)
        .build();

double widthScaleNaN = paramSize.getWidthScalingFactor();
assert Double.isNaN(widthScaleNaN) : "Expected width scale to be NaN when size is set";

System.out.println("__CHECK__ getWidthScalingFactor " + widthScale + ", " + widthScaleNaN);

